rm -rf /tmp/gate_repro && python3 -B scripts/run_cases.py --out /tmp/gate_repro 2>&1 | tail -25 && echo '--- diff vs pass_a cases.jsonl (normalized) ---' && python3 -I - <<'PY'
import json
def load(p):
    return {json.loads(l)['case_id']:json.loads(l) for l in open(p) if l.strip()}
a=load('logs/historical/pass_a/cases.jsonl'); b=load('/tmp/gate_repro/cases.jsonl')
for cid in a:
    x,y=a[cid],b[cid]
    same=(x.get('accepted'),x.get('exit_code'),x.get('message'))==(y.get('accepted'),y.get('exit_code'),y.get('message'))
    print(cid, "SAME" if same else "DIFF", "| passA:",x['accepted'],"| mine:",y['accepted'])
    if not same:
        print("   passA msg:",x.get('message'))
        print("   mine  msg:",y.get('message'))
PY

